//! Independently specified selected-pair/manual finish boundaries at OR70.
use gielinor_world::{assembly,grinding,tool_crafting,inventory::{Item,Inventory,StackType},stats::Stats,npc::RandomSource,simulation::{World,PlayerData,ActorId,Action},held_use::{Handler,Scope,Type,Request},CoordGrid};
struct NoDraw;impl RandomSource for NoDraw{fn below(&mut self,_:u32)->u32{panic!("manual finish drew RNG")}}
fn item(id:i32)->Option<Item>{Some(Item{id,count:1,vars:0})}
fn setup(helm:bool,slot:usize,reverse:bool,member:bool,current:i8,rate:i32)->(World,ActorId,Request){
 let(first,raw) = if helm{(1755,12927)}else{(10980,10981)};
 let mut inv=Inventory::new(28,StackType::Normal,false);for s in 0..28{inv.restore_slot(s,item(1931)).unwrap();}
 for s in [0,1]{inv.restore_slot(s,item(first)).unwrap();}for s in [slot,if slot==4{9}else{4}]{inv.restore_slot(s,item(raw)).unwrap();}inv.restore_slot(27,Some(Item{id:995,count:1000,vars:0})).unwrap();
 let mut stats=Stats::default();stats.set_base(3,10);stats.set_current(3,10);stats.set_base(12,1);stats.set_current(12,current);stats.set_fine_xp(12,0).unwrap();stats.set_current(1,0);stats.set_current(11,0);
 let mut w=World::default();w.collision.allocate(3200,3200,0);let mut d=PlayerData::new(1,"Independent manual finishing".into(),CoordGrid::new(3200,3200,0).unwrap(),stats);d.inventory=inv;d.xp_rate_hundreds=rate;w.queue_login(1,d).unwrap();w.tick().unwrap();let a=w.actors().next().unwrap();w.set_membership(a,member).unwrap();
 for id in[first,raw]{w.held_use_types.insert(id,Type{id,content:-1});}
 let handler=if helm{Handler::ToolCrafting(tool_crafting::Recipe{exchange:grinding::Recipe{tool:1755,input:12927,output:12929,members:true,animation:None},level:52,xp_tenths:1200,ticks:1,name:"serpentine helm",action:"carve",failure:None})}else{Handler::AssemblyImmediate(assembly::Recipe{first:10980,second:10981,output:10973,skill:12,level:87,base_xp:104,members:true})};w.held_use_handlers.register(Scope::Types,first,raw,handler).unwrap();w.drain_events();
 let h=if reverse{Request{selected_slot:slot as i32,selected_id:raw,target_slot:0,target_id:first}}else{Request{selected_slot:0,selected_id:first,target_slot:slot as i32,target_id:raw}};(w,a,h)
}

#[test]fn fifty_two_initial_refusals_conserve_whole_state(){let mut n=0;for helm in[false,true]{for reverse in[false,true]{for mode in 0..13{let(mut w,a,h)=setup(helm,17,reverse,true,99,125);match mode{0=>w.set_membership(a,false).unwrap(),1=>w.data_mut(a).unwrap().stats.set_current(12,if helm{51}else{86}),2=>w.data_mut(a).unwrap().xp_rate_hundreds=0,3=>{w.data_mut(a).unwrap().inventory.restore_slot(17,None).unwrap();},4|5=>{let mut v=w.data(a).unwrap().inventory.get(17).unwrap();if mode==4{v.vars=1;}else{v.count=2;}w.data_mut(a).unwrap().inventory.restore_slot(17,Some(v)).unwrap();},6=>{w.data_mut(a).unwrap().inventory.restore_slot(0,None).unwrap();},7|8=>{let mut v=w.data(a).unwrap().inventory.get(0).unwrap();if mode==7{v.vars=1;}else{v.count=2;}w.data_mut(a).unwrap().inventory.restore_slot(0,Some(v)).unwrap();},9=>{w.object_types.dummy.insert(if helm{12929}else{10973});},10=>w.set_modal_open(a,true).unwrap(),11=>w.request_logout(a).unwrap(),_=>w.data_mut(a).unwrap().xp_rate_hundreds=-1}let before=w.data(a).unwrap().clone();if w.prepare_held_use(a,h).is_ok(){let _=w.finish_held_use(a,h);}for _ in 0..10{w.tick_with_random(&mut NoDraw).unwrap();}assert_eq!(w.data(a).unwrap().inventory,before.inventory,"helm{helm} reverse{reverse} mode{mode}");assert_eq!(w.data(a).unwrap().stats,before.stats);n+=1;}}}assert_eq!(n,52);}
#[test]fn twenty_pending_helm_changes_cancel_selected_credit(){let mut n=0;for reverse in[false,true]{for mode in 0..10{let(mut w,a,h)=setup(true,17,reverse,true,99,125);w.prepare_held_use(a,h).unwrap();w.finish_held_use(a,h).unwrap();match mode{0=>{w.data_mut(a).unwrap().inventory.restore_slot(17,None).unwrap();},1=>{w.data_mut(a).unwrap().inventory.restore_slot(0,None).unwrap();},2=>{let mut v=w.data(a).unwrap().inventory.get(17).unwrap();v.vars=1;w.data_mut(a).unwrap().inventory.restore_slot(17,Some(v)).unwrap();},3=>w.set_membership(a,false).unwrap(),4=>w.data_mut(a).unwrap().stats.set_current(12,51),5=>w.data_mut(a).unwrap().xp_rate_hundreds=0,6=>{w.object_types.dummy.insert(12929);},7=>{w.set_modal_open(a,true).unwrap();w.set_modal_open(a,false).unwrap();},8=>{w.close_dialogs(a).unwrap();},_=>w.submit(a,Action::Walk{destination:CoordGrid::new(3201,3200,0).unwrap(),run:false}).unwrap()}let before=w.data(a).unwrap().clone();for _ in 0..10{w.tick_with_random(&mut NoDraw).unwrap();}assert_eq!(w.data(a).unwrap().inventory,before.inventory,"reverse{reverse} late{mode}");assert_eq!(w.data(a).unwrap().stats,before.stats);n+=1;}}assert_eq!(n,20);}
